def _examples(command_class):
    doc = command_class.__doc__ or ""
    return [
        line.strip()
        for line in doc.splitlines()
        if line.strip().startswith("az agentfabric ")
    ]


class AgentfabricScenario(ScenarioTest):

    def test_agentfabric_command_help(self):
        commands = (
            "agentfabric",
            "agentfabric member",
            "agentfabric aks",
            "agentfabric egress-trust-bundle",
            "agentfabric policy-group",
            *(command for command, _, _ in COMMANDS),
            *HELP_ONLY_COMMANDS,
        )
        for command in commands:
            try:
                self.cmd(f"az {command} --help")
            except SystemExit as ex:
                self.assertEqual(ex.code, 0, f"{command} help failed")

    def test_agentfabric_examples_parse(self):
        for command, module_name, class_name in COMMANDS:
            command_class = getattr(importlib.import_module(module_name), class_name)
            examples = _examples(command_class)
            self.assertTrue(examples, command)
            for example in examples:
                tokens = shlex.split(example)
                self.assertEqual(tokens[:2], ["az", "agentfabric"], example)
                escaped_example = example.replace("{", "{{").replace("}", "}}")
                try:
                    self.cmd(f"{escaped_example} --help")
                except SystemExit as ex:
                    self.assertEqual(ex.code, 0, f"Example failed to parse: {example}")


class AgentfabricGeneratedCommandTest(unittest.TestCase):

    def test_member_command_subset(self):
        from azure.cli.core import get_default_cli
        from azext_agentfabric import AgentfabricCommandsLoader
        from azext_agentfabric.aaz.latest.agentfabric import member
        loader = AgentfabricCommandsLoader(cli_ctx=get_default_cli())
        commands = loader.load_command_table(None)
        self.assertEqual(
            {name for name in commands if name.startswith("agentfabric member ")},
            {f"agentfabric member {name}" for name in ("show", "list", "wait")},
        )
        for name in ("Create", "Update", "Delete"):
            self.assertFalse(hasattr(member, name))
            self.assertIsNone(importlib.util.find_spec(member.__name__ + "._" + name.lower()))

    def test_attach_help_documents_entra_prerequisite(self):
        self.assertIn("--enable-aad", AksAttach.__doc__)
        self.assertIn("Managed identity alone does not enable", " ".join(AksAttach.__doc__.split()))

    def _operation(self, command_class, operation_name, arguments):
        ctx = AAZCommandCtx(MagicMock(), command_class._build_arguments_schema(), arguments)
        ctx._clients["MgmtClient"] = MagicMock()  # pylint: disable=protected-access
        return getattr(command_class, operation_name)(ctx=ctx)

    def test_all_commands_have_generated_examples(self):
        for command, module_name, class_name in COMMANDS:
            command_class = getattr(importlib.import_module(module_name), class_name)
            self.assertIn(":example:", command_class.__doc__, command)
            self.assertTrue(
                any(example.startswith(f"az {command}") for example in _examples(command_class)),
                command,
            )

    def test_all_operations_use_latest_public_api(self):
        from azure.cli.core.aaz import AAZHttpOperation
        for command, module_name, class_name in COMMANDS:
            command_class = getattr(importlib.import_module(module_name), class_name)
            for operation_class in vars(command_class).values():
                if not isinstance(operation_class, type) or not issubclass(operation_class, AAZHttpOperation):
                    continue
                operation = operation_class(ctx=MagicMock())
                operation.client.format_url.side_effect = lambda url, **_: url
                self.assertEqual(operation.query_parameters, {"api-version": "2026-10-07-preview"}, command)
                self.assertIn("/Microsoft.NetworkSecurity/", operation.url, command)
                self.assertNotIn("Private.NetworkSecurity", operation.url, command)
                self.assertFalse(operation.url.startswith("https://"), command)

